import {
    checkForCachedData,
    setCachedData,
} from "https://framer.com/m/cache-YMiL.js@b9aplVZjN51x28yfNK16"
import type { SearchIndex } from "./useSearch.ts"

const VERSION = 1
const defaultLocaleId = "default"

export function isDefaultLocaleId(
    localeId: string | undefined
): localeId is string {
    return !localeId || localeId === "default"
}

const INDEX_KEY = "searchIndexCache"

function getIndexKey(localeId: string | undefined) {
    if (isDefaultLocaleId(localeId)) return INDEX_KEY
    return `${INDEX_KEY}-${localeId}`
}

const METADATA_KEY = "searchCacheMetadata"

function getMetadataKey(localeId: string | undefined) {
    if (isDefaultLocaleId(localeId)) return METADATA_KEY
    return `${METADATA_KEY}-${localeId}`
}

export async function getCachedIndex(
    localeId: string | undefined,
    indexHash: string | undefined
): Promise<
    | {
          status: "fresh" | "stale"
          searchIndex: SearchIndex
          indexHash?: string
      }
    | { status: "miss" }
> {
    // A check here for metadata can be added later if we need to
    // migrate or expire the index. Though most likely, any version change
    // should result in deleting the cache and starting again.

    const metadataKey = getMetadataKey(localeId)
    const indexKey = getIndexKey(localeId)

    const [metadata, cachedIndex] = await Promise.all([
        checkForCachedData(metadataKey),
        checkForCachedData(indexKey),
    ])

    if (cachedIndex) {
        return {
            status:
                indexHash && metadata?.indexHash === indexHash
                    ? "fresh"
                    : "stale",
            searchIndex: cachedIndex,
            indexHash: metadata?.indexHash,
        }
    }

    return { status: "miss" }
}

export function setCachedIndex(
    localeId: string | undefined,
    index: SearchIndex,
    indexHash: string
) {
    const indexKey = getIndexKey(localeId)
    setCachedData(indexKey, index)

    const metadata = {
        version: VERSION,
        timestamp: Date.now(),
        indexHash,
    }

    const metadataKey = getMetadataKey(localeId)
    setCachedData(metadataKey, metadata)
}
